const news = $input.first().json;
const securities = $input.item.json;

const newsArray = Array.isArray(news) ? news : [news];
const securitiesArray = Array.isArray(securities) ? securities : [securities];

const matches = [];

for (const article of newsArray) {
  const searchText = `${article.title || ''} ${article.description || ''}`.toLowerCase();

  for (const security of securitiesArray) {
    const symbolMatch = searchText.includes(security.symbol.toLowerCase());
    const nameMatch = searchText.includes(security.name.toLowerCase());
    const keywordMatch = (security.keywords || []).some(kw => 
      searchText.includes(kw.toLowerCase())
    );
    const sectorMatch = security.sector && searchText.includes(security.sector.toLowerCase());

    if (symbolMatch || nameMatch || keywordMatch || sectorMatch) {
      let impact = 'neutral';
      const positiveWords = ['rises', 'gains', 'up', 'surge', 'beat', 'positive', 'growth', 'bull'];
      const negativeWords = ['falls', 'drops', 'down', 'plunge', 'miss', 'negative', 'decline', 'bear'];

      const textLower = `${article.title} ${article.description || ''}`.toLowerCase();
      const positiveCount = positiveWords.filter(w => textLower.includes(w)).length;
      const negativeCount = negativeWords.filter(w => textLower.includes(w)).length;

      if (positiveCount > negativeCount + 1) impact = 'positive';
      else if (negativeCount > positiveCount + 1) impact = 'negative';

      matches.push({
        news_id: article.id,
        security_id: security.id,
        security_symbol: security.symbol,
        headline: article.title,
        impact,
        matched_by: symbolMatch ? 'symbol' : nameMatch ? 'name' : keywordMatch ? 'keyword' : 'sector',
        matched_at: new Date().toISOString()
      });
    }
  }
}

if (matches.length === 0) return [];
return matches.map(m => ({ json: m }));

