const prediction = $input.first().json;

const historicalContext = await $http.get(`${$env.QUANTIVE_BASE_URL}/api/v1/analytics/historical/${prediction.portfolio_id}?limit=30}`);
const marketContext = await $http.get(`${$env.QUANTIVE_BASE_URL}/api/v1/market/current`);
const newsContext = await $http.get(`${$env.QUANTIVE_BASE_URL}/api/v1/news/sentiment`);

const technicalIndicators = {
  rsi: prediction.indicators?.rsi || null,
  macd: prediction.indicators?.macd || null,
  sma_20: prediction.indicators?.sma_20 || null,
  sma_50: prediction.indicators?.sma_50 || null,
  bollinger_upper: prediction.indicators?.bollinger_upper || null,
  bollinger_lower: prediction.indicators?.bollinger_lower || null,
  atr: prediction.indicators?.atr || null,
  obv: prediction.indicators?.obv || null,
  vwap: prediction.indicators?.vwap || null
};

const trendStrength = technicalIndicators.rsi 
  ? (technicalIndicators.rsi > 70 ? 'overbought' : technicalIndicators.rsi < 30 ? 'oversold' : 'neutral')
  : 'unknown';

const explanation = {
  prediction_id: prediction.id,
  portfolio_id: prediction.portfolio_id,
  predicted_value: prediction.predicted_value,
  confidence: prediction.confidence,
  factors: {
    historical_trend: historicalContext.data?.trend || 'insufficient_data',
    market_conditions: marketContext.data?.conditions || 'unknown',
    technical_analysis: {
      indicators: technicalIndicators,
      trend_strength: trendStrength,
      signal: prediction.signal || 'hold'
    },
    news_sentiment: newsContext.data?.overall_sentiment || 'neutral',
    key_drivers: prediction.drivers || []
  },
  explanation_text: `This prediction of $${prediction.predicted_value} with ${prediction.confidence}% confidence is based on ${historicalContext.data?.trend || 'historical'} trends, current market conditions that are ${marketContext.data?.conditions || 'neutral'}, and technical indicators showing ${trendStrength} conditions. The news sentiment is ${newsContext.data?.overall_sentiment || 'neutral'}.`,
  generated_at: new Date().toISOString()
};

return [{ json: explanation }];

const predictions = $input.all();

const errors = predictions.map(p => {
  const predicted = parseFloat(p.json.predicted_value);
  const actual = parseFloat(p.json.actual_value);
  const error = Math.abs(predicted - actual);
  const absolutePercentageError = actual !== 0 ? (error / Math.abs(actual)) * 100 : 0;

  return {
    prediction_id: p.json.prediction_id,
    portfolio_id: p.json.portfolio_id,
    predicted_value: predicted,
    actual_value: actual,
    absolute_error: error,
    absolute_percentage_error: absolutePercentageError,
    created_at: p.json.created_at
  };
});

const n = errors.length;
if (n === 0) {
  return [{ json: { mae: 0, rmse: 0, mape: 0, error_rate: 0, errors: [], sample_size: 0 } }];
}

const mae = errors.reduce((sum, e) => sum + e.absolute_error, 0) / n;
const mse = errors.reduce((sum, e) => sum + Math.pow(e.absolute_error, 2), 0) / n;
const rmse = Math.sqrt(mse);
const mape = errors.reduce((sum, e) => sum + e.absolute_percentage_error, 0) / n;
const errorRate = errors.filter(e => e.absolute_percentage_error > 10).length / n * 100;

return [{
  json: {
    mae: Math.round(mae * 100) / 100,
    rmse: Math.round(rmse * 100) / 100,
    mape: Math.round(mape * 100) / 100,
    error_rate: Math.round(errorRate * 100) / 100,
    sample_size: n,
    errors: errors.slice(0, 100),
    calculated_at: new Date().toISOString()
  }
}];

