const metrics = $input.first().json;
const errors = metrics.errors || [];

const patterns = {
  high_errors: errors.filter(e => e.absolute_percentage_error > 20),
  recent_errors: errors.filter(e => new Date(e.created_at) > new Date(Date.now() - 6 * 60 * 60 * 1000)),
  portfolio_distribution: {},
  time_distribution: {}
};

for (const error of errors) {
  patterns.portfolio_distribution[error.portfolio_id] = 
    (patterns.portfolio_distribution[error.portfolio_id] || 0) + 1;

  const hour = new Date(error.created_at).getHours();
  patterns.time_distribution[`${hour}:00`] = 
    (patterns.time_distribution[`${hour}:00`] || 0) + 1;
}

return [{
  json: {
    ...metrics,
    patterns,
    analysis: {
      high_error_count: patterns.high_errors.length,
      recent_error_count: patterns.recent_errors.length,
      most_affected_portfolio: Object.entries(patterns.portfolio_distribution)
        .sort((a, b) => b[1] - a[1])[0]?.[0] || 'none',
      analysis_time: new Date().toISOString()
    }
  }
}];

const checks = [
  {
    name: 'missing_values',
    query: `SELECT 
      (SELECT COUNT(*) FROM market_data WHERE data IS NULL) as market_null,
      (SELECT COUNT(*) FROM predictions WHERE predicted_value IS NULL) as predictions_null,
      (SELECT COUNT(*) FROM news_articles WHERE title IS NULL) as news_null,
      (SELECT COUNT(*) FROM watchlist_securities WHERE symbol IS NULL) as watchlist_null;`
  },
  {
    name: 'outlier_detection',
    query: `WITH stats AS (
      SELECT AVG(predicted_value) as mean, STDDEV(predicted_value) as stddev
      FROM predictions WHERE created_at >= NOW() - INTERVAL '24 hours'
    )
    SELECT COUNT(*) as outlier_count
    FROM predictions, stats
    WHERE ABS(predicted_value - mean) > 3 * stddev
    AND created_at >= NOW() - INTERVAL '24 hours';`
  },
  {
    name: 'staleness',
    query: `SELECT
      (SELECT MAX(updated_at) FROM market_data) as last_market_data,
      (SELECT MAX(created_at) FROM predictions) as last_prediction,
      (SELECT MAX(published_at) FROM news_articles) as last_news,
      (SELECT MAX(last_checked) FROM watchlist_securities) as last_watchlist;`
  },
  {
    name: 'schema_validation',
    query: `SELECT
      (SELECT COUNT(*) FROM information_schema.columns WHERE table_name = 'market_data' AND is_nullable = 'NO') as required_columns,
      (SELECT COUNT(*) FROM information_schema.table_constraints WHERE constraint_type = 'PRIMARY KEY') as primary_keys;`
  }
];

return checks.map(check => ({ json: check }));

const results = $input.all();
const now = new Date();

let qualityScore = 100;
const issues = [];

for (const result of results) {
  const data = result.json;

  if (data.name === 'missing_values' && data) {
    const totalNulls = (data.market_null || 0) + (data.predictions_null || 0) + 
                       (data.news_null || 0) + (data.watchlist_null || 0);
    if (totalNulls > 0) {
      qualityScore -= totalNulls * 2;
      issues.push({ type: 'missing_values', count: totalNulls, severity: totalNulls > 100 ? 'high' : 'medium' });
    }
  }

  if (data.name === 'outlier_detection' && data) {
    if (data.outlier_count > 0) {
      qualityScore -= data.outlier_count * 5;
      issues.push({ type: 'outliers', count: data.outlier_count, severity: data.outlier_count > 10 ? 'high' : 'low' });
    }
  }

  if (data.name === 'staleness' && data) {
    const staleThreshold = 24 * 60 * 60 * 1000;
    if (data.last_market_data && (now - new Date(data.last_market_data)) > staleThreshold) {
      qualityScore -= 15;
      issues.push({ type: 'stale_market_data', age_hours: Math.round((now - new Date(data.last_market_data)) / 3600000), severity: 'high' });
    }
    if (data.last_prediction && (now - new Date(data.last_prediction)) > staleThreshold) {
      qualityScore -= 10;
      issues.push({ type: 'stale_predictions', age_hours: Math.round((now - new Date(data.last_prediction)) / 3600000), severity: 'medium' });
    }
  }
}

qualityScore = Math.max(0, Math.min(100, qualityScore));

return [{
  json: {
    quality_score: qualityScore,
    issues,
    check_timestamp: now.toISOString(),
    checks_performed: results.length,
    passed: qualityScore >= 80
  }
}];

