const technicalAnalysis = {
  rsi: indicators.rsi || null,
  macd: indicators.macd || null,
  sma_20: indicators.sma_20 || null,
  sma_50: indicators.sma_50 || null,
  ema_12: indicators.ema_12 || null,
  ema_26: indicators.ema_26 || null,
  bollinger_upper: indicators.bollinger_upper || null,
  bollinger_lower: indicators.bollinger_lower || null,
  atr: indicators.atr || null,
  obv: indicators.obv || null,
  vwap: indicators.vwap || null
};

let rsiSignal = 'neutral';
if (technicalAnalysis.rsi) {
  if (technicalAnalysis.rsi > 70) rsiSignal = 'overbought';
  else if (technicalAnalysis.rsi < 30) rsiSignal = 'oversold';
}

let macdSignal = 'neutral';
if (technicalAnalysis.macd) {
  macdSignal = technicalAnalysis.macd > 0 ? 'bullish' : 'bearish';
}

const newsSentiment = newsData?.sentiment || 'neutral';
const topHeadlines = (newsData?.articles || []).slice(0, 5).map(a => a.title);

const explanation = {
  symbol: stockData.symbol,
  price_performance: {
    current_price: price,
    change: change,
    change_percent: changePercent,
    volume: volume,
    market_cap: marketCap
  },
  technical_analysis: {
    indicators: technicalAnalysis,
    rsi_signal: rsiSignal,
    macd_signal: macdSignal,
    trend: changePercent > 0 ? 'bullish' : changePercent < 0 ? 'bearish' : 'neutral'
  },
  news_analysis: {
    sentiment: newsSentiment,
    top_headlines: topHeadlines,
    article_count: newsData?.articles?.length || 0
  },
  peer_comparison: stockData.peers || [],
  risk_factors: stockData.risks || [],
  summary: `${stockData.symbol} is currently trading at $${price} (${changePercent > 0 ? '+' : ''}${changePercent}%). ` +
    `Technical indicators show ${rsiSignal} conditions with ${macdSignal} MACD signal. ` +
    `News sentiment is ${newsSentiment} with ${topHeadlines.length} recent articles. ` +
    `Volume is ${volume.toLocaleString()} shares.`,
  generated_at: new Date().toISOString()
};

return [{ json: explanation }];

const signals = $input.first().json;
const signalArray = Array.isArray(signals) ? signals : [signals];

const analyzed = signalArray.map(signal => {
  let strength = 0;
  let direction = 'neutral';

  if (signal.technical_score) strength += signal.technical_score * 0.3;
  if (signal.sentiment_score) strength += signal.sentiment_score * 0.25;
  if (signal.prediction_score) strength += signal.prediction_score * 0.35;
  if (signal.fundamental_score) strength += signal.fundamental_score * 0.1;

  if (strength > 60) direction = 'bullish';
  else if (strength < 40) direction = 'bearish';

  const confidence = Math.min(100, Math.max(0, strength));

  return {
    signal_id: signal.id,
    symbol: signal.symbol,
    strength: Math.round(strength * 100) / 100,
    direction,
    confidence,
    components: {
      technical: signal.technical_score || 0,
      sentiment: signal.sentiment_score || 0,
      prediction: signal.prediction_score || 0,
      fundamental: signal.fundamental_score || 0
    },
    analyzed_at: new Date().toISOString()
  };
});

return analyzed.map(a => ({ json: a }));

