const signals = $input.all();

const conflicts = [];

for (const signal of signals) {
  const components = signal.json.components || {};

  const hasConflict = (
    (components.technical > 60 && components.sentiment < 40) ||
    (components.technical < 40 && components.sentiment > 60) ||
    (components.prediction > 60 && components.fundamental < 40) ||
    (components.prediction < 40 && components.fundamental > 60)
  );

  if (hasConflict) {
    let severity = 'low';
    const divergence = Math.max(
      Math.abs(components.technical - components.sentiment),
      Math.abs(components.prediction - components.fundamental)
    );

    if (divergence > 40) severity = 'high';
    else if (divergence > 20) severity = 'medium';

    conflicts.push({
      symbol: signal.json.symbol,
      signal_id: signal.json.signal_id,
      divergence,
      severity,
      components,
      detected_at: new Date().toISOString()
    });
  }
}

return conflicts.map(c => ({ json: c }));

