const metrics = $input.first().json;

const report = {
  date: new Date().toISOString().split('T')[0],
  generated_at: new Date().toISOString(),
  market_performance: {
    sp500: metrics.market?.sp500 || {},
    nasdaq: metrics.market?.nasdaq || {},
    dow: metrics.market?.dow || {},
    bonds: metrics.market?.bonds || {},
    fx: metrics.market?.fx || {},
    vix: metrics.market?.vix || null
  },
  portfolio_performance: {
    total_value: metrics.portfolio?.total_value || 0,
    daily_pnl: metrics.portfolio?.daily_pnl || 0,
    daily_pnl_pct: metrics.portfolio?.daily_pnl_pct || 0,
    positions: metrics.portfolio?.positions || []
  },
  prediction_accuracy: {
    total_predictions: metrics.predictions?.total || 0,
    accurate_predictions: metrics.predictions?.accurate || 0,
    accuracy_rate: metrics.predictions?.accuracy_rate || 0,
    avg_confidence: metrics.predictions?.avg_confidence || 0
  },
  system_health: {
    data_quality_score: metrics.system?.data_quality || 100,
    uptime: metrics.system?.uptime || '99.9%',
    alerts_today: metrics.system?.alerts || 0,
    errors_today: metrics.system?.errors || 0
  },
  key_alerts: metrics.alerts || [],
  summary: `Daily Report for ${new Date().toISOString().split('T')[0]}\n\n` +
    `Market: S&P 500 ${metrics.market?.sp500?.change || 'N/A'}%, ` +
    `NASDAQ ${metrics.market?.nasdaq?.change || 'N/A'}%\n` +
    `Portfolio: $${(metrics.portfolio?.total_value || 0).toLocaleString()} (${metrics.portfolio?.daily_pnl_pct || 0}%)\n` +
    `Predictions: ${metrics.predictions?.accuracy_rate || 0}% accuracy\n` +
    `Data Quality: ${metrics.system?.data_quality || 100}%\n` +
    `Alerts: ${metrics.system?.alerts || 0}`
};

return [{ json: report }];

const alertData = $input.first().json;
const body = alertData.body || alertData;

const thresholds = {
  price_change: { critical: 10, high: 5, medium: 2 },
  volume_spike: { critical: 500, high: 300, medium: 200 },
  yield_change: { critical: 0.5, high: 0.3, medium: 0.1 },
  fx_change: { critical: 3, high: 2, medium: 1 }
};

let severity = 'medium';
let alertType = body.type || 'unknown';
let value = body.value || body.change || 0;

const threshold = thresholds[alertType];
if (threshold) {
  const absValue = Math.abs(value);
  if (absValue >= threshold.critical) severity = 'critical';
  else if (absValue >= threshold.high) severity = 'high';
  else severity = 'medium';
}

if (body.severity) severity = body.severity;

return [{
  json: {
    ...body,
    severity,
    alert_type: alertType,
    value,
    received_at: new Date().toISOString()
  }
}];

